.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  border: 0;
}
.sr-only-focusable:active,
.sr-only-focusable:focus {
  position: static;
  width: auto;
  height: auto;
  margin: 0;
  overflow: visible;
  clip: auto;
}
.time-control-main {
  border-radius: 2px; }

.time-control-main > .row {
  margin-left: 0px;
  margin-right: 0px; }

.time-control-main > .top-row.row {
  border: 1px solid #e0e0e0;
  border-bottom: 0px;
  border-radius: 3px 3px 0 0; }

.time-control-main > .content-row.row {
  border: 1px solid #e0e0e0;
  border-top: 0px;
  border-radius: 0 0 3px 3px;
  margin-bottom: 10px; }

.time-control-main > .top-row.row .col-xs-11,
.time-control-main > .top-row.row .col-xs-6,
.time-control-main > .top-row.row .col-xs-1 {
  padding: 0px; }

.time-control-main > .top-row.row input,
.time-control-main > .top-row.row .btn {
  background: transparent;
  border: none;
  border-bottom: 1px solid #e0e0e0;
  padding-top: 10px;
  padding-bottom: 10px;
  height: 36px; }

.time-control-main > .top-row.row .btn {
  padding-left: 0px;
  padding-right: 0px; }

.time-control-main > .tags-row.row {
  margin-top: 10px; }

.time-control-main > .tags-row.row > .tags-outline {
  border: 1px solid #e0e0e0;
  border-radius: 2px;
  padding: 10px;
  padding-bottom: 7px;
  /* inset for the tag bottom margin */ }

.time-control-main > .tags-row.row .btn {
  background: #d2d2d2;
  border: none;
  margin-right: 5px;
  margin-bottom: 5px; }

.time-control-main > .buttons-row.row > .btn {
  margin-left: 10px; }

.time-control-main > .buttons-row.row > .btn:last-child {
  margin-left: 0px; }

.time-control-main > .top-row.row input {
  box-shadow: none;
  text-align: center;
  border-radius: 0px;
  margin-bottom: -1px;
  background: transparent; }

.time-control-main > .top-row.row input:focus {
  border-bottom: 1px solid #239a8e; }

.time-control-main > .top-row.row .btn {
  color: #e0e0e0;
  border-radius: 0px;
  box-shadow: none; }

.time-control-main > .top-row.row .btn:hover,
.time-control-main > .top-row.row .btn:active {
  background: #f0f0f0; }

.time-control-main > .top-row.row .btn.left-but {
  border-right: 1px solid #e0e0e0; }

.time-control-main > .top-row.row .btn.right-but {
  border-left: 1px solid #e0e0e0; }

.time-control-main > .top-row.row span.dash {
  content: "-";
  position: absolute;
  left: 0%;
  margin-left: -3px;
  color: #555;
  margin-top: 9px; }

.slick-overridden > .scroll-area {
  position: relative;
  margin-top: 10px;
  min-height: 280px;
  /*max-height: 280px;*/
  overflow-x: hidden; }

.time-control-main .centercard {
  position: relative; }

.time-control-main .adjacent-table {
  margin-top: 0px; }

.time-control-main .calendar-year {
  float: left;
  padding-left: 10px;
  padding-right: 10px; }

.time-control-main .current-week {
  background: #99ddff;
  color: white; }

.time-control-main .current-week.hover,
.time-control-main .current-week:hover {
  background: #66ccff;
  color: white; }

.time-control-main .kinetic-scroll-outer.year-scroll {
  position: relative;
  height: 40px;
  width: 100%;
  border-top: 1px solid #e0e0e0;
  border-bottom: 1px solid #e0e0e0;
  margin-top: 15px; }

.time-control-main ul.years-container li {
  float: left;
  border-left: 1px solid #ddd;
  text-align: center;
  padding-top: 10px;
  padding-bottom: 10px;
  cursor: pointer; }

.time-control-main ul.years-container li:hover {
  background: #f7f7f7; }

.time-control-main ul.years-container li:first-child {
  border-left: 0px; }

.time-control-main ul.years-container li > span {
  font-weight: bold; }

.time-control-main .scroll-area {
  overflow-y: hidden; }

.slider table {
  width: 100%;
  margin-top: 3px; }

.slider table tr td {
  text-align: center;
  padding: 8px 1px 8px 1px;
  background-color: #f5f5f5;
  border-right: 1px solid #fff;
  border-bottom: 1px solid #fff; }

.slider table tr td.disabled {
  color: #ccc;
  opacity: 0.5; }

.slider table tr td.disabled:hover {
